function accountsActionButton(action){const tabs={transfer:'accounts',received:'accounts',pay:'payables',reimburse:'reimbursements',adjustment:'accounts',collection:'receivables',partial:'payables',consolidated:'payables',procurement:'vendors'};const tab=tabs[action]||'all';return{inline_keyboard:[[{text:'Open on mobile',url:base()+'/expenses.html?tab='+encodeURIComponent(tab)}],[{text:'⬅️ Accounts menu',callback_data:'am:home'}]]};}
const NATIVE_ACCOUNT_ACTIONS=['received','reimburse','adjustment','collection','partial','consolidated','procurement'];
function nativeActionHelp(action){return{
  received:'Send: SANKI 3645 5000 Customer refund',
  pay:'Send: EX-00052 3645 720',
  reimburse:'Send: EX-00052 3645 720',
  adjustment:'Send: SANKI 3645 add 500 Balance correction',
  collection:'Send: RCV-00001 3448 500',
  partial:'Send: EX-00012 3645 2000',
  consolidated:'Send: EX-00012,EX-00013 | 3645 | 5000',
  procurement:'Send: PO-00012 3645 5000'
}[action]||'';}
function parseNativeAction(action,raw){const t=String(raw||'').trim();let m,d={action,date:new Date().toISOString().slice(0,10)};
  if(action==='received'&&(m=t.match(/^(SANKI|SAMAST|PERSONAL)\s+(\d{4}|cash)\s+([0-9,]+(?:\.\d{1,2})?)\s+(.+)$/i)))Object.assign(d,{nature:m[1].toUpperCase(),account:m[2],amount:Number(m[3].replace(/,/g,'')),source:m[4],note:m[4],receiptType:'other_income'});
  else if(action==='adjustment'&&(m=t.match(/^(SANKI|SAMAST|PERSONAL)\s+(\d{4}|cash)\s+(add|deduct)\s+([0-9,]+(?:\.\d{1,2})?)\s+(.+)$/i)))Object.assign(d,{nature:m[1].toUpperCase(),account:m[2],direction:m[3].toLowerCase(),amount:Number(m[4].replace(/,/g,'')),note:m[5]});
  else if(['pay','reimburse','partial'].includes(action)&&(m=t.match(/^(EX-\d+)\s+(\d{4}|cash)\s+([0-9,]+(?:\.\d{1,2})?)$/i)))Object.assign(d,{id:m[1].toUpperCase(),account:m[2],amount:Number(m[3].replace(/,/g,''))});
  else if(action==='collection'&&(m=t.match(/^(RCV-\d+)\s+(\d{4}|cash)\s+([0-9,]+(?:\.\d{1,2})?)$/i)))Object.assign(d,{id:m[1].toUpperCase(),account:m[2],amount:Number(m[3].replace(/,/g,''))});
  else if(action==='procurement'&&(m=t.match(/^([A-Z]+-[A-Z0-9-]+)\s+(\d{4}|cash)\s+([0-9,]+(?:\.\d{1,2})?)$/i)))Object.assign(d,{id:m[1].toUpperCase(),account:m[2],amount:Number(m[3].replace(/,/g,''))});
  else if(action==='consolidated'){const p=t.split('|').map(x=>x.trim());if(p.length===3&&/^\d{4}$|^cash$/i.test(p[1])&&Number(p[2].replace(/,/g,''))>0)Object.assign(d,{ids:p[0].split(',').map(x=>x.trim().toUpperCase()).filter(x=>/^EX-\d+$/.test(x)),account:p[1],amount:Number(p[2].replace(/,/g,''))});}
  return(d.amount>0&&(d.id||d.ids&&d.ids.length||d.nature))?d:null;}
function nativeActionPreview(d){return'<b>Confirm '+esc(d.action.replace(/_/g,' '))+'</b>\n\n'+(d.nature?'Entity: <b>'+esc(d.nature)+'</b>\n':'')+(d.id?'Reference: <b>'+esc(d.id)+'</b>\n':'')+(d.ids?'Bills: <b>'+esc(d.ids.join(', '))+'</b>\n':'')+'Account: <b>'+esc(d.account)+'</b>\nAmount: <b>'+money(d.amount)+'</b>\n'+(d.direction?'Direction: '+esc(d.direction)+'\n':'')+(d.source?'Source: '+esc(d.source)+'\n':'')+(d.note?'Note: '+esc(d.note)+'\n':'')+'Date: '+esc(d.date)+'\n\nNothing is recorded until Confirm.';}
