function pagedCategoryButtons(prefix,page){const categories=require('./expenses').telegramBusinessCategories(),size=10,p=Math.max(0,Math.min(Number(page)||0,Math.ceil(categories.length/size)-1)),start=p*size,rows=[];for(let i=start;i<Math.min(categories.length,start+size);i+=2)rows.push(categories.slice(i,i+2).map((name,j)=>({text:name,callback_data:prefix+'cat:'+(i+j)})));const nav=[];if(p>0)nav.push({text:'◀ Previous',callback_data:prefix+'catpage:'+(p-1)});if(start+size<categories.length)nav.push({text:'Next ▶',callback_data:prefix+'catpage:'+(p+1)});if(nav.length)rows.push(nav);rows.push([{text:'❌ Cancel',callback_data:prefix.startsWith('am:')?'am:qcancel':'ba:cancel'}]);return{inline_keyboard:rows};}
