function runNativeAction(target,d){const e=require('./expenses'),common={amount:d.amount,date:d.date,account:d.account,paymentProof:d.proof,proof:d.proof,note:d.note};
  if(d.action==='received')return e.telegramApi('POST','/api/expenses/receipts',target,{body:Object.assign(common,{nature:d.nature,source:d.source,receiptType:d.receiptType})});
  if(d.action==='adjustment')return e.telegramApi('POST','/api/expenses/balances',target,{body:{nature:d.nature,adjust:{account:d.account,amount:d.amount,direction:d.direction,note:d.note,date:d.date,proof:d.proof}}});
  if(d.action==='reimburse')return e.telegramApi('POST','/api/expenses/:id/reimburse',target,{params:{id:d.id},body:common});
  if(d.action==='collection')return e.telegramApi('POST','/api/expenses/receivables/:id/receive',target,{params:{id:d.id},body:common});
  if(d.action==='procurement')return e.telegramApi('POST','/api/expenses/procurement-payables/:id/pay',target,{params:{id:d.id},body:common});
  if(d.action==='consolidated')return e.telegramApi('POST','/api/expenses/batch-pay',target,{body:Object.assign(common,{expenseIds:d.ids})});
  return e.telegramApi('POST','/api/expenses/:id/pay',target,{params:{id:d.id},body:common});}
function capturePreview(p){const x=p.payload||{},kind=p.kind==='receipt'?'money received':'expense';return '<b>Please confirm this PERSONAL '+kind+'</b>\n\n'+(p.kind==='receipt'?'<b>Source:</b> '+esc(x.source||'—'):'<b>Particulars:</b> '+esc(x.particulars||'—')+'\n<b>Paid to:</b> '+esc(x.vendor||'—')+'\n<b>Category:</b> '+esc(x.ledger||'—'))+'\n<b>Account:</b> '+esc(x.account||'—')+'\n<b>Amount:</b> '+money(x.amount)+'\n<b>Date:</b> '+esc(x.date||new Date().toISOString().slice(0,10))+'\n\nNothing is recorded until you press Confirm.';}
function sendCapturePreview(chatId,p,personal){p.phase='review';p.expiresAt=Date.now()+1800000;return(personal?tgPersonal:tg)('sendMessage',{chat_id:chatId,text:capturePreview(p),parse_mode:'HTML',reply_markup:{inline_keyboard:[[{text:'✅ Confirm',callback_data:'personal_confirm'},{text:'✏️ Edit',callback_data:'personal_edit'}],[{text:'❌ Cancel',callback_data:'personal_cancel'}]]}});}
function applyCaptureEdit(p,raw){const text=String(raw||'').trim(),x=p.payload||{};let m;if((m=text.match(/^amount\s*[:=-]?\s*(?:₹|rs\.?|inr)?\s*([0-9][0-9,]*(?:\.\d{1,2})?)$/i))){x.amount=Number(m[1].replace(/,/g,''));return x.amount>0;}if((m=text.match(/^account\s*[:=-]?\s*(cash|[0-9]{2,4})$/i))){x.account=m[1];return true;}if((m=text.match(/^(?:particulars?|purpose|narration)\s*[:=-]?\s*(.+)$/i))){x.particulars=m[1].trim();if(p.kind==='receipt')x.source=x.particulars;else{const c=inferPersonalCategory(x.particulars,x.vendor);x.ledger=c.ledger;}return!!x.particulars;}if((m=text.match(/^category\s*[:=-]?\s*(.+)$/i))){x.ledger=m[1].trim();return!!x.ledger;}return false;}
function completePending(p,target){const expenses=require('./expenses');if(p.kind==='receipt'){const result=expenses.createTelegramPersonalReceipt(Object.assign({},p.payload,{username:target.username}));if(!result.success)return{ok:false,text:'Could not record this receipt: '+result.error};const x=result.receipt;return{ok:true,text:'✅ PERSONAL money received recorded\n'+x.id+' · '+money(x.amount)+' · '+x.source+'\nReceived in: '+x.account};}const result=expenses.createTelegramPersonalExpense(Object.assign({},p.payload,{username:target.username}));if(!result.success)return{ok:false,text:'Could not record this expense: '+result.error};const e=result.expense;return{ok:true,text:'✅ PERSONAL expense recorded and marked paid\n'+e.id+' · '+money(e.amount)+' · '+e.particulars+'\nAccount: '+e.account+'\nCategory: '+e.ledger};}
function canApproveBusiness(target,nature){const r=target&&target.roles||[],wanted=String(nature||'SANKI').toUpperCase();if(wanted==='PERSONAL')return r.includes('owner');if(r.includes('owner')||r.includes('admin'))return true;return wanted==='SAMAST'?r.includes('samast_accounting'):r.includes('accounting');}
function approverChatIds(s,nature){return Object.keys(s.chats||{}).filter(id=>canApproveBusiness(userSummary(s.chats[id]&&s.chats[id].name),nature));}
function approvalText(e){const paymentState=e.paidAlready?'✅ <b>Already paid by claimant</b> — approve for reimbursement':'⏳ <b>Not paid yet</b> — approve first, then pay the vendor';return '<b>'+esc(e.nature||'SANKI')+' · '+esc(e.id)+'</b>\nClaimant: <b>'+esc(e.createdBy||e.claimant||'—')+'</b>\nVendor: <b>'+esc(e.vendor||'—')+'</b>\nParticulars: '+esc(e.particulars||'—')+'\nAmount: <b>'+money(e.amount)+'</b>\nPayment status: '+paymentState+'\nCategory: '+esc(e.ledger||'Not assigned')+'\nPayment type: '+esc(e.paymentType||'—');}
