function approvalCategoryButtons(expenseId,page){const categories=require('./expenses').telegramBusinessCategories(),size=10,p=Math.max(0,Math.min(Number(page)||0,Math.ceil(categories.length/size)-1)),start=p*size,rows=[];for(let i=start;i<Math.min(categories.length,start+size);i+=2)rows.push(categories.slice(i,i+2).map((name,j)=>({text:name,callback_data:'ba:cat:'+expenseId+':'+(i+j)})));const nav=[];if(p>0)nav.push({text:'◀ Previous',callback_data:'ba:catpage:'+expenseId+':'+(p-1)});if(start+size<categories.length)nav.push({text:'Next ▶',callback_data:'ba:catpage:'+expenseId+':'+(p+1)});if(nav.length)rows.push(nav);rows.push([{text:'Cancel',callback_data:'ba:cancel:'+expenseId}]);return{inline_keyboard:rows};}
function notifyExpenseForApproval(e){const s=load(),ids=approverChatIds(s,e.nature),personal=String(e.nature||'').toUpperCase()==='PERSONAL'&&personalConfigured(),photo=personal?tgPersonalPhoto:tgPhoto;return Promise.all(ids.map(id=>photo(id,e.billPhoto,'🧾 <b>New expense awaiting approval</b>\n'+approvalText(e),approvalButtons(e)).then(()=>e.qrPhoto?photo(id,e.qrPhoto,'Vendor QR for <b>'+esc(e.id)+'</b>'):null))).then(()=>({sent:ids.length}));}
function sendPaymentOptions(chatId,e){if(e.paidAlready)return reply(chatId,'✅ '+e.id+' approved. It was already paid personally; reimbursement is now pending.');const buttons={inline_keyboard:[[{text:'💳 Record payment',callback_data:'bp:start:'+e.id},{text:'Pay later',callback_data:'bp:later:'+e.id}],[{text:'Open in app',url:base()+'/expenses.html?focus='+encodeURIComponent(e.id)}]]};return(e.qrPhoto?tgPhoto(chatId,e.qrPhoto,'✅ <b>'+esc(e.id)+' approved</b>\nVendor QR · '+esc(e.vendor)+' · '+money(e.amount),buttons):tg('sendMessage',{chat_id:chatId,text:'✅ <b>'+esc(e.id)+' approved</b>\n'+esc(e.vendor)+' · '+money(e.amount),parse_mode:'HTML',reply_markup:buttons}));}
function sendPersonalPaymentOptions(chatId,e){if(e.paidAlready)return reply(chatId,'✅ '+e.id+' approved. It was already paid personally; reimbursement is now pending.',true);const buttons={inline_keyboard:[[{text:'💳 Record payment',callback_data:'bp:start:'+e.id},{text:'Pay later',callback_data:'bp:later:'+e.id}],[{text:'Open in app',url:base()+'/expenses.html?focus='+encodeURIComponent(e.id)}]]};return(e.qrPhoto?tgPersonalPhoto(chatId,e.qrPhoto,'✅ <b>'+esc(e.id)+' approved</b>\nVendor QR · '+esc(e.vendor)+' · '+money(e.amount),buttons):tgPersonal('sendMessage',{chat_id:chatId,text:'✅ <b>'+esc(e.id)+' approved</b>\n'+esc(e.vendor)+' · '+money(e.amount),parse_mode:'HTML',reply_markup:buttons}));}
function businessEdit(d,raw){const t=String(raw||'').trim();let m;if((m=t.match(/^amount\s*[:=-]?\s*(?:₹|rs\.?|inr)?\s*([0-9][0-9,]*(?:\.\d{1,2})?)$/i))){d.changes.amount=Number(m[1].replace(/,/g,''));return true;}for(const spec of [['vendor','vendor'],['particulars','particulars?'],['ledger','category'],['nature','entity'],['type','type'],['paymentType','payment type']]){const re=new RegExp('^'+spec[1]+'\\s*[:=-]?\\s*(.+)$','i');if((m=t.match(re))){d.changes[spec[0]]=m[1].trim();return true;}}return false;}
