router.post('/api/telegram/setup',(req,res)=>{if(!owner(req))return res.status(403).json({success:false,error:'Owner only.'});if(!configured())return res.json({success:false,error:'TELEGRAM_BOT_TOKEN is not configured on Railway.'});const s=load();if(!s.webhookSecret)s.webhookSecret=crypto.randomBytes(24).toString('hex');Promise.all([tg('getMe',{}),tg('setWebhook',{url:base()+'/api/telegram/webhook/'+s.webhookSecret,secret_token:s.webhookSecret,allowed_updates:['message','callback_query']})]).then(([me,hook])=>{if(me&&me.ok)s.botUsername=me.result.username;save(s);res.json(hook&&hook.ok?{success:true,botUsername:s.botUsername}:{success:false,error:(hook&&hook.description)||'Webhook setup failed.'});});});
router.post('/api/telegram/personal-setup',(req,res)=>{if(!owner(req))return res.status(403).json({success:false,error:'Owner only.'});if(!personalConfigured())return res.json({success:false,error:'TELEGRAM_PERSONAL_BOT_TOKEN is not configured on Railway.'});const s=load();if(!s.personalWebhookSecret)s.personalWebhookSecret=crypto.randomBytes(24).toString('hex');Promise.all([tgPersonal('getMe',{}),tgPersonal('setWebhook',{url:base()+'/api/telegram/personal-webhook/'+s.personalWebhookSecret,secret_token:s.personalWebhookSecret,allowed_updates:['message','callback_query'],drop_pending_updates:false})]).then(([me,hook])=>{if(me&&me.ok)s.personalBotUsername=me.result.username;save(s);if(!me||!me.ok)return res.status(502).json({success:false,error:me&&me.description||'The Personal bot token is invalid.'});res.json(hook&&hook.ok?{success:true,botUsername:s.personalBotUsername}:{success:false,error:hook&&hook.description||'Personal webhook setup failed.'});});});
router.post('/api/telegram/test',(req,res)=>{if(!owner(req))return res.status(403).json({success:false,error:'Owner only.'});const username=String(req.body&&req.body.username||'').trim();if(username){const target=userSummary(username);if(!target)return res.status(404).json({success:false,error:'User not found.'});return notifyUser(target.username,'🔔 <b>Your SANKI Telegram notifications are working.</b>').then(r=>res.json(r.sent?{success:true,sent:r.sent,username:target.username}:{success:false,sent:0,error:'This user has not linked Telegram yet.'}));}notify('🔔 <b>SANKI Telegram notifications are working.</b>').then(r=>res.json({success:true,sent:r.sent}));});
router.post('/api/telegram/unlink',(req,res)=>{if(!owner(req))return res.status(403).json({success:false,error:'Owner only.'});const target=userSummary(req.body&&req.body.username);if(!target)return res.status(404).json({success:false,error:'User not found.'});const s=load(),key=target.username.toLowerCase(),ids=chatIdsForUser(s,key),requested=String(req.body&&req.body.chatId||''),remove=requested?ids.filter(id=>id===requested):ids;if(requested&&!remove.length)return res.status(404).json({success:false,error:'Telegram connection not found.'});const left=ids.filter(id=>!remove.includes(id));if(left.length)s.userChats[key]=left;else delete s.userChats[key];remove.forEach(id=>{delete s.chats[id];delete(s.chatMeta||{})[id];});save(s);res.json({success:true,username:target.username,wasLinked:remove.length>0,removed:remove.length,remaining:left.length});});
ensureWebhookUpdates();
